from fractions import Fraction
from sympy import symbols, factor
x = symbols("x")

def check(case, simplified, original, answer, excluded):
    print(case)
    print(f"  simplified: {simplified}, excluded {excluded}")
    for v in range(-3, 4):
        if v in excluded:
            print(f"    x = {v}: excluded")
        else:
            print(f"    x = {v}: original {original(v)}, answer {answer(v)}")

def product1(v):
    return Fraction(v * v - 4, v + 3) * Fraction(v + 3, v - 2)

def answer1(v):
    return v + 2

def quotient2(v):
    return Fraction(v * v - 1, v + 2) / Fraction(v + 1, (v + 2) ** 2)

def answer2(v):
    return (v - 1) * (v + 2)

def product3(v):
    return Fraction(v - 2, v + 1) * Fraction(v + 1, 2 - v)

def answer3(v):
    return -1

check("Case 1 · multiplying: (x^2 - 4)/(x + 3) * (x + 3)/(x - 2)",
      factor((x**2 - 4)/(x + 3) * (x + 3)/(x - 2)), product1, answer1, [-3, 2])
check("Case 2 · dividing: (x^2 - 1)/(x + 2) / ((x + 1)/(x + 2)^2)",
      factor((x**2 - 1)/(x + 2) / ((x + 1)/(x + 2)**2)), quotient2, answer2, [-2, -1])
check("Case 3 · opposite factors: (x - 2)/(x + 1) * (x + 1)/(2 - x)",
      factor((x - 2)/(x + 1) * (x + 1)/(2 - x)), product3, answer3, [-1, 2])

