from fractions import Fraction

n = int(input())
for i in range(n):
    p = int(input())
    q = int(input())
    r = int(input())
    s = int(input())
    for x in range(-2, 3):
        if x == q or x == s or x == r:
            print(f"x = {x}: excluded")
        else:
            print(f"x = {x}: {Fraction(x - p, x - q) / Fraction(x - r, x - s)}")

n = int(input())
for i in range(n):
    a = int(input())
    p = int(input())
    c = int(input())
    B = -(p + a)
    C = c
    print(f"B = {B}, C = {C}")
    bound = abs(B) + abs(C)
    found = False
    for u in range(-bound, bound + 1):
        v = B - u
        if u <= v and u * v == C and not found:
            found = True
            roots = [-v, -u]
            if u == v:
                roots = [-u]
            good = 0
            for r in roots:
                if r == p:
                    print(f"x = {r}: extraneous")
                else:
                    print(f"x = {r}: solution")
                    good = good + 1
            if good == 0:
                print("no solution")
